exec('"""Copy freshly made videos into docs/videos so the website can show them. Keeps the last 14 days."""\nimport json, shutil, sys\nfrom datetime import date, timedelta\nfrom pathlib import Path\n\nROOT = Path(__file__).resolve().parent.parent\nOUT, SITE = ROOT / "output", ROOT / "docs" / "videos"\nKEEP_DAYS = 14\n\nindex_file = SITE / "index.json"\nindex = json.loads(index_file.read_text(encoding="utf-8")) if index_file.exists() else []\nknown = {x["id"] for x in index}\n\nfor day in sorted(OUT.glob("*")) if OUT.exists() else []:\n    if not day.is_dir():\n        continue\n    ideas = []\n    if (day / "ideas.json").exists():\n        ideas = json.loads((day / "ideas.json").read_text(encoding="utf-8"))\n    for folder in sorted(day.glob("[0-9][0-9]-*")):\n        video = folder / "video.mp4"\n        if not video.exists():\n            continue\n        vid = f"{day.name}-{folder.name}"\n        if vid in known:\n            continue\n        dest = SITE / vid\n        dest.mkdir(parents=True, exist_ok=True)\n        shutil.copy2(video, dest / "video.mp4")\n        caption = (folder / "caption.txt").read_text(encoding="utf-8") if (folder / "caption.txt").exists() else ""\n        (dest / "caption.txt").write_text(caption, encoding="utf-8")\n        n = int(folder.name[:2])\n        title = ideas[n - 1].get("title") if 0 < n <= len(ideas) else folder.name[3:].replace("-", " ").title()\n        index.append({"id": vid, "date": day.name, "title": title,\n                      "video": f"videos/{vid}/video.mp4", "caption": caption})\n\ncutoff = (date.today() - timedelta(days=KEEP_DAYS)).isoformat()\nkeep = []\nfor x in index:\n    if x["date"] >= cutoff:\n        keep.append(x)\n    else:\n        shutil.rmtree(SITE / x["id"], ignore_errors=True)\nkeep.sort(key=lambda x: x["id"], reverse=True)\nindex_file.write_text(json.dumps(keep, indent=2, ensure_ascii=False), encoding="utf-8")\nprint(f"Published. {len(keep)} videos on the site.")\n')
